export const SUPPLEMENT_CATEGORIES = [
  "Proteine",
  "Pre-workout",
  "Creatina",
  "Aminoacidi / EAA",
  "Intra-workout",
  "Post-workout",
  "Brucia grassi",
  "Vitamine / Multivitamin",
  "Minerali",
  "Omega / Acidi grassi",
  "Articolazioni",
  "Sonno / Recovery",
  "Focus / Nootropi",
  "Salute ormonale",
  "Digestione / Probiotici",
  "Idratazione / Elettroliti",
  "Barrette / Snack",
  "Mass gainer",
  "Pump (stim-free)",
  "Collagene"
];
export function searchSupplementCatalog(query, opts = {}) {
  const q = String(query || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  const mode = (opts && opts.mode) || 'all';
  if (!q) return SUPPLEMENT_CATALOG.slice(0, 40);
  return SUPPLEMENT_CATALOG.filter((s) => {
    const ingredientBlob = [s.ingredient, s.active_ingredient, s.category, (!s.brand ? s.name : '')].filter(Boolean).join(' ').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const brandBlob = [s.brand, s.name, s.category].filter(Boolean).join(' ').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const blob = mode === 'ingredient' ? ingredientBlob : (mode === 'brand' ? brandBlob : [ingredientBlob, brandBlob].join(' '));
    if (blob.includes(q)) return true;
    return blob.split(/\s+/).some((w) => w.startsWith(q));
  }).slice(0, 40);
}
export default { SUPPLEMENT_CATALOG, SUPPLEMENT_CATEGORIES, searchSupplementCatalog };
